-- 1. Chống âm kho nguyên vật liệu ở cấp bảng dữ liệu
ALTER TABLE raw_materials
  ADD CONSTRAINT chk_non_negative_available
  CHECK (on_hand_qty >= reserved_qty AND reserved_qty >= 0);

-- 2. Khóa BOM nguyên tử khi phát hành Lệnh sản xuất (Work Order)
CREATE OR REPLACE FUNCTION reserve_bom_for_work_order(p_wo_id UUID)
RETURNS VOID AS $$
DECLARE
  v_req RECORD;
BEGIN
  FOR v_req IN
    SELECT b.material_id,
           SUM(b.qty_per_unit * (1 + b.scrap_rate) * woi.quantity) AS total_needed
    FROM work_order_items woi
    JOIN bom_recipes b ON b.sku_id = woi.sku_id AND b.size_code = woi.size_code
    WHERE woi.work_order_id = p_wo_id
    GROUP BY b.material_id
    ORDER BY b.material_id -- Tránh deadlock khi nhiều lệnh chạy song song
  LOOP
    UPDATE raw_materials
    SET reserved_qty = reserved_qty + v_req.total_needed,
        updated_at = NOW()
    WHERE id = v_req.material_id
      AND (on_hand_qty - reserved_qty) >= v_req.total_needed;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INSUFFICIENT_MATERIAL_STOCK: %', v_req.material_id;
    END IF;
  END LOOP;

  UPDATE work_orders SET status = 'BOM_RESERVED' WHERE id = p_wo_id AND status = 'DRAFT';
END;
$$ LANGUAGE plpgsql;

-- 3. Chuyển công đoạn bằng mã QR idempotent & Cổng QA bắt buộc
CREATE OR REPLACE FUNCTION advance_qr_stage(
  p_qr_code TEXT,
  p_expected_from TEXT,
  p_next_stage TEXT,
  p_operator_id UUID,
  p_scan_idempotency_key TEXT
) RETURNS TEXT AS $$
DECLARE
  v_current TEXT;
BEGIN
  INSERT INTO qr_scan_events(idempotency_key, qr_code, stage, operator_id)
  VALUES (p_scan_idempotency_key, p_qr_code, p_next_stage, p_operator_id)
  ON CONFLICT (idempotency_key) DO NOTHING;

  IF NOT FOUND THEN
    RETURN 'DUPLICATE_SCAN_IGNORED';
  END IF;

  SELECT current_stage INTO v_current FROM unit_qr_items WHERE qr_code = p_qr_code FOR UPDATE;

  IF v_current <> p_expected_from THEN
    RAISE EXCEPTION 'INVALID_STAGE_TRANSITION: current=% expected=%', v_current, p_expected_from;
  END IF;

  IF p_next_stage = 'READY_TO_SHIP' AND v_current <> 'QA_PASSED' THEN
    RAISE EXCEPTION 'QA_GATE_BLOCKED: Cannot ship before QA_PASSED';
  END IF;

  UPDATE unit_qr_items SET current_stage = p_next_stage, updated_at = NOW() WHERE qr_code = p_qr_code;
  RETURN 'TRANSITION_OK';
END;
$$ LANGUAGE plpgsql;
